#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    printf("배열 크기: ");
    scanf("%d", &n);

    // 동적 배열 생성
    int *arr = malloc(n * sizeof(int));

    if (arr == NULL) {
        return 1;
    }

    // 배열처럼 사용
    for (int i = 0; i < n; i++) {
        arr[i] = i * 10;
    }

    for (int i = 0; i < n; i++) {
        printf("arr[%d] = %d\n", i, arr[i]);
    }

    free(arr);
    return 0;
}
